        "question": "Fabrikalardan nehirlere bırakılan kimyasal atıklar, sulardaki ağır metal oranını artırır.\nAşağıdakilerden hangisi su kirliliğine ve canlılarda zehirlenmeye yol açan \"Ağır Metaller\" grubuna giren bir element **değildir**?",
