        "question": "Temizlik amacıyla kullanılan \"Sabun\" ve \"Deterjan\"ın çevreye etkileri karşılaştırıldığında;\nI. Sabun bitkisel ve hayvansal yağlardan üretildiği için doğada bakteriler tarafından kolayca parçalanır (zararı çok azdır).\nII. Deterjanlar petrol türevidir, içerdikleri kimyasallar (fosfatlar, yüzey aktifler) doğada zor parçalanır ve su kirliliğine yol açar.\nIII. Deterjanlar sert (kireçli) sularda hiç temizlemezken, sabun her suda kusursuz temizler.\nifadelerinden hangileri **doğrudur**?",
