        "id": "KIM-TYT-K05-T05-S02",
        "question": "Büyük okyanuslarda seyahat eden gemiler veya tatlı suyun hiç olmadığı Arap yarımadasındaki ülkeler, deniz suyundan içme suyu (tatlı su) elde etmek için ileri bir teknoloji kullanırlar.\nTuzlu suya çok yüksek bir basınç uygulanarak, suyun yarı geçirgen bir zardan (membrandan) \"tuzun bırakılıp sadece saf suyun\" karşıya geçmesi esasına dayanan bu sistemin adı nedir?",
