        "solution": "Dünyadaki suyun %97.5'i Okyanus/Denizdir (I en büyük).\nKalan %2.5 tatlı suyun büyük bir kısmı (%68'i civarı) Buzullar ve Kalıcı karlardır (II ikinci büyük).\nGeriye kalanın çok büyük bir kısmı (%30 civarı) ulaşılamayan Derin Yeraltı Sularıdır (III üçüncü).\nBizim içtiğimiz ve kullandığımız tüm Göller, Nehirler ve yüzey suları ise toplam suyun sadece %0.3'ü kadardır (IV en küçük).\nSıralama: Okyanus (I) > Buzul (II) > Yeraltı Suyu (III) > Göller/Nehirler (IV). (A seçeneği)."
