        "id": "KIM-TYT-K05-T05-S09",
        "question": "Biyolojik arıtma tesislerinde (Atıksu arıtma), kanalizasyondan gelen kirli sular içindeki devasa organik atıkların (dışkı, yemek artığı vb.) temizlenmesi için kimyasal asit/baz yerine hangi **canlı/doğal mekanizma** kullanılır?",
