          {
            "id": "B",
            "text": "Ağır Metaller ($Pb, Hg, Cd$) $\\rightarrow$ Su kaynaklarında ve toprakta çözünerek canlı dokularında birikir (Toksik etki)."
          },
          {
            "id": "C",
            "text": "Fosfatlı Deterjanlar $\\rightarrow$ Göllerdeki besin miktarını artırarak alg patlamasına (Ötrofikasyona) neden olur."
          },
          {
            "id": "D",
            "text": "Karbondioksit ($CO_2$) $\\rightarrow$ Güneşten gelen zararlı UV ışınlarını yeryüzüne çekerek radyasyon kirliliğine (mutasyona) neden olur."
          },
          {
            "id": "E",
            "text": "Pestisitler (Tarım İlaçları) $\\rightarrow$ Toprakta kalıcı zehirlenmeye ve besin zincirinde biyobirikime neden olur."
          }
