        "correctAnswer": "D",
        "difficulty": "hard",
        "solution": "A, B, C ve E seçeneklerindeki fail-suç eşleştirmeleri tamamen DOĞRUDUR.\nAncak D seçeneğindeki ifade kesinlikle yanlıştır. Karbondioksit ($CO_2$), Güneşten gelen zararlı UV (Morötesi) ışınlarını \"çekerek radyasyon kirliliğine (mutasyona)\" NEDEN OLMAZ. UV'yi tutan şey Ozon ($O_3$) tabakasıdır. $CO_2$'nin suçu \"Güneş ışığını (Isıyı / Kızılötesini)\" geri bırakmayıp dünyayı ısıtmaktır (Sera Etkisi). Mutasyon yapmak değildir."
