        "question": "\"Smog\" (Sis-Duman kelimelerinin birleşimi - Hava kirliliği), iki ana türe ayrılır: Londra Tipi Smog ve Los Angeles Tipi Smog.\nBunların arasındaki temel farkları anlatan aşağıdaki ifadelerden hangisi **doğrudur**?",
