        "question": "Plastik şişeler (PET şişeler), doğaya atıldıklarında yüzlerce yıl parçalanmazlar. Ayrıca güneş altında veya okyanus dalgalarıyla çok küçük parçalara (5 milimetreden küçük) ayrılarak su canlılarının hücrelerine kadar girerler.\nGünümüzde besin zincirine ve hatta insan kanına kadar girdiği kanıtlanan bu çok küçük plastik parçacıklarına ne ad verilir?",
