        "question": "Kimya dersinde \"Su Arıtımı\" ünitesini işleyen bir öğretmen, \"Aktif Karbon\" filtresinden bahsetmektedir.\nAktif karbon filtresinin (kömürsü sünger yapının) su arıtma cihazlarında (veya filtreli sürahilerde) kullanımının asıl amacı nedir?",
