        "question": "Ekolojik sistemlerde (göl ve ormanlarda), pH değerinin 5.0'ın altına düşmesi (Asitlenmesi) toprak ve su kimyasını bozar.\nAsit yağmurlarının toprakta yarattığı en büyük **kimyasal tahribat (yıkım)** aşağıdakilerden hangisidir?",
