        "correctAnswer": "D",
        "difficulty": "easy",
        "solution": "Sıfır Atık hiyerarşisi (Ters piramit) 3R veya 5R kuralına dayanır: Reddet (Refuse), Azalt (Reduce), Yeniden Kullan (Reuse), Geri Dönüştür (Recycle), Çürüt (Rot).\nEn kötü seçenek gömmektir (B). Geri dönüşüm (C) iyidir ama harika değildir çünkü elektrik harcar.\nEn tepe nokta, en harika seçenek: \"Atığın oluşmasını ÖNLEMEK (Hiç almamak, poşet reddetmek, matara kullanmak, tasarruf etmek) \"tir. Çöp oluşmazsa sorun da oluşmaz. (D)."
