        "id": "KIM-TYT-K05-T11-S04",
        "question": "Aşağıdaki gazlardan hangisi, atmosferde hem **asit yağmurlarına** sebep olan hem de şehir üzerinde **sarımsı fotokimyasal sis (smog)** oluşturan zehirli gaz grubundandır?",
