        "question": "Fabrikalardan çıkan atıksuların arıtılmasında fiziksel, kimyasal ve biyolojik arıtma yöntemleri kullanılır.\nAşağıdakilerden hangisi atıksu arıtımında \"Fiziksel Arıtma\" aşamasında (ilk aşamada) yapılan bir işlem **değildir**?",
