        "id": "KIM-TYT-K05-T13-S01",
        "question": "İçme suyu şebekelerinde suların \"pH değeri\" sağlık açısından düzenli olarak kontrol edilir.\nDünya Sağlık Örgütü (WHO) ve TS 266 standartlarına göre kaliteli ve sağlıklı bir içme suyunun pH değeri hangi aralıkta (hafif bazik/nötre yakın) olmalıdır?",
