        "question": "Su kirliliği yaratan maddelerden biri olan \"Sentetik Yüzey Aktif Maddeler (Deterjanlar)\", nehir ve göllere karıştığında oksijen transferini durduran kalın bir köpük tabakası oluştururlar.\nBuna göre deterjanların göllerdeki köpürmesinin **su ekosistemine olan fiziksel zararı** aşağıdakilerden hangisidir?",
