        "id": "KIM-TYT-K05-T14-S09",
        "question": "Plastik çöpler doğada parçalanmadığı için çevreye devasa zararlar verir.\nAncak son yıllarda mısır nişastası, patates veya şeker kamışından elde edilen laktik asit kullanılarak üretilen ve doğaya atıldığında topraktaki bakteriler tarafından kolayca yenilip (parçalanıp) aylar içinde tamamen yok olan özel plastikler üretilmektedir.\nDoğa dostu olan bu tür plastiklere verilen genel isim nedir?",
