        "question": "Doğada bulunan Cıva ($Hg$), fabrikalardan veya termik santrallerden inorganik formda göllere karıştığında, gölün dibindeki anaerobik bakteriler tarafından işlenerek çok daha zehirli, kana ve beyne kolayca geçen organik bir cıva formuna dönüştürülür.\nJaponya'da \"Minamata Hastalığı\" olarak bilinen felakete neden olan bu **organik cıva** bileşiği aşağıdakilerden hangisidir?",
