        "solution": "PET (Polietilen Tereftalat) şişeler sadece Karbon, Hidrojen ve Oksijenden oluşur. Mükemmel erirler.\nFakat aralarına karışan PVC (Polivinil KLORÜR), yapısında \"KLOR\" atomu barındırır. PVC ısıtıldığında kolayca parçalanır ve içindeki klor, Hidrojen Klorür ($HCl$ - Tuz ruhu) gazı olarak açığa çıkar. Bu çok kuvvetli asidik gaz, hem fabrikanın makinelerini paslandırır hem de PET eriyiğini sarartıp asitlendirerek tüm partiyi çöpe çevirir. Sebebi PVC'den çıkan $HCl$'dir. (B)."
