            "id": "D",
            "text": "Logaritmik olduğu için 0.1 birimlik düşüş, asitliğin (Hidrojen iyonunun) yaklaşık **%26 - %30** oranında devasa bir artış gösterdiği (asitleştiği) anlamına gelir."
