        "question": "Küresel ısınma sonucu deniz sularının (okyanusların) ısınması, sadece buzulları eritmekle kalmaz, aynı zamanda okyanusların \"CO2 emme (Yutak olma)\" kapasitesini de felç eder.\nOkyanus suyu ısındıkça atmosferdeki Karbondioksiti ($CO_2$) emme (çözme) kapasitesinin **DÜŞMESİNİN** temel kimyasal kuralı nedir?",
