        "question": "Büyükbaş hayvancılık (özellikle sığır yetiştiriciliği) küresel ısınmanın en büyük faillerinden biri olarak gösterilir.\nBunun sebebi sadece ineklerin Metan ($CH_4$) gazı üretmesi DEĞİLDİR. Hayvancılığın iklim krizine olan diğer devasa (dolaylı) çevresel zararı (Karbon ayak izi) aşağıdakilerden hangisidir?",
