        "question": "Küresel iklim krizinde \"Okyanus Asitlenmesi\" mercan resiflerini (Corals) ve kabuklu deniz canlılarını (İstiridye, Yengeç) doğrudan tehdit eder.\nOkyanus suyunun asitlenmesinin (pH'ın düşmesinin), mercanların ve istiridyelerin kabuk yapmasını (büyümesini) **kimyasal olarak nasıl zorlaştırdığı** aşağıdakilerden hangisinde doğru açıklanmıştır?",
