          {
            "id": "B",
            "text": "En Üst: Önleme-Reddetme (Refuse/Reduce - Atığı hiç üretmemek) / En Alt: Vahşi Depolama (Doğrudan çöpe gömme)"
          },
          {
            "id": "C",
            "text": "En Üst: Yakarak Enerji Üretme / En Alt: Kompost Yapma"
          },
          {
            "id": "D",
            "text": "En Üst: Vahşi Depolama / En Alt: Önleme"
          },
          {
            "id": "E",
            "text": "En Üst: Geri Dönüşüm / En Alt: Önleme"
          }
