            "text": "Havaya her gün binlerce ton zehirli gaz (CFC) salan bir sprey fabrikasının, ambalajının üzerine sahte bir \"Doğa Dostu Yaprak\" resmi çizip, hiçbir kanıt sunmadan \"Çevreyi seviyoruz\" yazması."
