          {
            "id": "C",
            "text": "Kloroflorokarbon (CFC)"
          },
          {
            "id": "D",
            "text": "Karbonmonoksit ($CO$)"
          },
          {
            "id": "E",
            "text": "Kükürtdioksit ($SO_2$)"
          }
