        "question": "Atmosferdeki \"Azot ($N_2$)\" gazı çok kararlı ve eylemsiz bir moleküldür (Üçlü bağ içerir). İnsanlar, bitkiler veya hayvanlar bu gazı doğrudan soluyarak (veya kökleriyle çekerek) protein üretemezler.\nHavadaki inorganik Azot gazını ($N_2$), bitkilerin kullanabileceği Amonyak ($NH_3$) veya Nitrat formuna \"Sabitleyebilen (Fikse edebilen - Azot Fiksayonu)\" **DOĞAL BİYOLOJİK (İnsan dışı)** ajanlar aşağıdakilerden hangisidir?",
